INSERT INTO route (id,name,subtitle,description,duration_minutes,difficulty,tags,suitable_for,cover_prompt,sort_no) VALUES
  (1,'北京皇家文化二日游','两天读懂六百年古都','串联皇城、长城与皇家园林，适合第一次到北京的深度文化之旅。',390,3,'历史,研学,亲子','亲子,研学,朋友','北京皇家文化二日游,中国旅游路线风景合集,高清风光摄影',1),
  (2,'江南园林水乡五日游','一园一古镇，梦回江南','从苏州园林到水乡古镇，再到杭州西湖，品味最江南的诗意生活。',460,2,'园林,水乡,摄影','情侣,朋友,亲子','江南园林水乡五日游,中国旅游路线风景合集,高清风光摄影',2),
  (3,'黄山徽文化三日游','登天下奇山，宿画里乡村','黄山看奇松云海，宏村西递品徽派建筑与徽州美食。',320,4,'登山,古村,摄影','朋友,情侣,摄影爱好者','黄山徽文化三日游,中国旅游路线风景合集,高清风光摄影',3),
  (4,'巴渝山水四日游','8D魔幻都市与世界地质奇观','山城夜景、火锅、古镇与武隆天坑，立体重庆一次玩透。',320,4,'都市,美食,震撼','朋友,情侣','巴渝山水四日游,中国旅游路线风景合集,高清风光摄影',4),
  (5,'九寨黄龙川西秘境五日游','奔赴人间瑶池与童话世界','成都出发，深入阿坝高原，看遍彩池、雪山与藏羌风情。',250,2,'自然风光,摄影,徒步','朋友,独自,摄影爱好者','九寨黄龙川西秘境五日游,中国旅游路线风景合集,高清风光摄影',5),
  (6,'云南滇西北风情六日游','大理风花雪月，丽江柔软时光','环洱海、逛古城、登雪山、入高原秘境，经典云南路线。',390,4,'古城,雪山,民宿','情侣,朋友','云南滇西北风情六日游,中国旅游路线风景合集,高清风光摄影',6),
  (7,'海南海岛度假四日游','阳光沙滩与热带雨林','亚龙湾嬉水、蜈支洲岛潜水、南山祈福，适合全家过冬度假。',320,4,'海岛,度假,亲子','亲子,情侣','海南海岛度假四日游,中国旅游路线风景合集,高清风光摄影',7),
  (8,'丝绸之路西北七日游','从长安到敦煌的千年通道','长城、石窟、丹霞、大漠与天山，一条线读懂丝路文明。',530,4,'丝路,历史,摄影','研学,朋友,摄影爱好者','丝绸之路西北七日游,中国旅游路线风景合集,高清风光摄影',8),
  (9,'西藏心灵净化之旅','在世界屋脊与自己对话','布达拉宫、大昭寺与圣湖神山，循序渐进适应高原。',320,4,'朝圣,高原,摄影','独自,朋友','西藏心灵净化之旅,中国旅游路线风景合集,高清风光摄影',9),
  (10,'桂林山水阳朔三日游','舟行碧波上，人在画中游','漓江竹筏、阳朔西街、龙脊梯田，尽享甲天下的山水。',250,4,'山水,竹筏,摄影','情侣,朋友,亲子','桂林山水阳朔三日游,中国旅游路线风景合集,高清风光摄影',10),
  (11,'张家界凤凰四日游','悬浮山与沱江夜','张家界峰林、天门山玻璃栈道，再到凤凰古城放慢脚步。',180,4,'奇峰,古镇,刺激','朋友,情侣','张家界凤凰四日游,中国旅游路线风景合集,高清风光摄影',11),
  (12,'东三省冰雪四日游','在冰雪童话世界里撒欢','冰雕、雾凇、天池与东北烟火气，冬季限定的浪漫。',370,4,'冰雪,冬季,亲子','亲子,朋友','东三省冰雪四日游,中国旅游路线风景合集,高清风光摄影',12),
  (13,'齐鲁文化三日游','登泰山而小天下，访三孔而知春秋','山水与圣人故里并重，山东经典研学线路。',320,4,'登山,研学,历史','研学,亲子,老人','齐鲁文化三日游,中国旅游路线风景合集,高清风光摄影',13),
  (14,'中原文化四日游','十三朝古都与功夫之乡','石窟、少林、汴梁繁华与太行山水，河南精华一线串联。',370,4,'历史,武术,山水','研学,朋友,亲子','中原文化四日游,中国旅游路线风景合集,高清风光摄影',14),
  (15,'贵州山水民族四日游','山地公园省的瀑、洞、寨','黄果树、小七孔、西江苗寨与梵净山，多彩贵州不负期待。',320,4,'瀑布,民族,避暑','朋友,亲子','贵州山水民族四日游,中国旅游路线风景合集,高清风光摄影',15),
  (16,'新疆环线八日游','一半花海一半雪山','湖泊、草原、雪山、古城与图瓦村落，新疆是一种瘾。',390,4,'自驾,草原,湖泊','朋友,情侣,摄影爱好者','新疆环线八日游,中国旅游路线风景合集,高清风光摄影',16);
INSERT INTO route_spot (route_id,spot_id,day_no,step_no,stay_minutes,narration) VALUES
(1,1,1,1,40,'欢迎来到第1站「故宫博物院」。这里位于北京北京，北京重量级历史文化地标，承载着深厚的中华文明记忆，是研学旅行的必到之处。本站看点是核心遗址与珍贵文物。建议请讲解或租用语音导览器，周一部分博物馆闭馆，室内展馆请勿使用闪光灯。建议停留约40分钟，门票60元，开放时间08:30-17:30。'),
(1,2,1,2,40,'欢迎来到第2站「天坛公园」。这里位于北京北京，北京著名宗教文化圣地，建筑、造像与信仰氛围令人心生敬畏。本站看点是镇寺之宝与造像艺术。殿内请勿大声喧哗与随意拍摄，尊重宗教仪轨；香火区域注意防火。建议停留约40分钟，门票34元，开放时间07:30-17:00。'),
(1,6,1,3,40,'欢迎来到第3站「恭王府」。这里位于北京北京，北京古典园林建筑的代表，一步一景、移步换景，尽显中国人的造景智慧。本站看点是标志性古建与中轴对称之美。穿舒适步行鞋，亭台楼阁门槛较多；园内花木请勿攀折，拍照注意错峰。建议停留约40分钟，门票40元，开放时间08:00-17:30。'),
(1,3,2,1,40,'欢迎来到第4站「颐和园」。这里位于北京北京，北京古典园林建筑的代表，一步一景、移步换景，尽显中国人的造景智慧。本站看点是标志性古建与中轴对称之美。穿舒适步行鞋，亭台楼阁门槛较多；园内花木请勿攀折，拍照注意错峰。建议停留约40分钟，门票30元，开放时间08:00-17:30。'),
(1,4,2,2,40,'欢迎来到第5站「八达岭长城」。这里位于北京北京，北京重量级历史文化地标，承载着深厚的中华文明记忆，是研学旅行的必到之处。本站看点是核心遗址与珍贵文物。建议请讲解或租用语音导览器，周一部分博物馆闭馆，室内展馆请勿使用闪光灯。建议停留约40分钟，门票40元，开放时间08:30-17:30。'),
(1,10,2,3,40,'欢迎来到第6站「国家体育场(鸟巢)」。这里位于北京北京，北京热门休闲度假地，适合情侣、亲子放松身心，尽享慢节奏假期。本站看点是网红度假打卡点。海边紫外线强请做好防晒，参与水上项目务必穿救生衣，泡汤每次不超过20分钟。建议停留约40分钟，门票50元，开放时间全天开放。'),
(2,61,1,1,40,'欢迎来到第1站「拙政园」。这里位于江苏苏州，苏州古典园林建筑的代表，一步一景、移步换景，尽显中国人的造景智慧。本站看点是标志性古建与中轴对称之美。穿舒适步行鞋，亭台楼阁门槛较多；园内花木请勿攀折，拍照注意错峰。建议停留约40分钟，门票80元，开放时间08:00-17:30。'),
(2,62,1,2,40,'欢迎来到第2站「留园」。这里位于江苏苏州，苏州古典园林建筑的代表，一步一景、移步换景，尽显中国人的造景智慧。本站看点是标志性古建与中轴对称之美。穿舒适步行鞋，亭台楼阁门槛较多；园内花木请勿攀折，拍照注意错峰。建议停留约40分钟，门票55元，开放时间08:00-17:30。'),
(2,63,1,3,40,'欢迎来到第3站「周庄古镇」。这里位于江苏苏州，苏州最具烟火气的古镇古村，老街、美食与民俗在此交融，适合慢下来住一晚。本站看点是保存完好的老街巷肌理。古镇石板路多，建议穿防滑鞋；夜景出片可在亮灯前后拍摄，民宿节假日请提前预订。建议停留约40分钟，门票100元，开放时间全天开放(展馆09:00-21:00)。'),
